            aOrbiterB = ((((aWandererE + RotL64(aIngress, 39U)) + RotL64(aCarry, 21U)) + 0x223D5A40595ED6C3ULL) + aOrbiterAssignSaltE[(((31U - aIndex) + 29U)) & S_SALT1]) + aNonceWordJ;
