            aOrbiterE = (aOrbiterE + aOrbiterD) + 0x242941AA713A0A47ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterE) ^ 0x76B4EFC6E6C40A02ULL) ^ aOrbiterUpdateSaltE[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x1F11A343B929A9BDULL), 21U);
