            //
            aWandererD = aWandererD ^ ((RotL64(aScatter, 43U) + RotL64(aOrbiterK, 60U)) + aOrbiterC);
            aWandererK = aWandererK + ((RotL64(aCross, 26U) + aOrbiterB) + RotL64(aOrbiterD, 51U));
            aWandererA = aWandererA ^ ((RotL64(aIngress, 35U) + aOrbiterJ) + RotL64(aOrbiterA, 21U));
            aWandererF = aWandererF + ((((RotL64(aPrevious, 5U) + RotL64(aOrbiterC, 41U)) + aOrbiterJ) + RotL64(aCarry, 13U)) + aPhaseBWandererUpdateSaltC[(((31U - aIndex) + 14U)) & S_SALT1]);
            aWandererG = aWandererG ^ (((RotL64(aScatter, 19U) + RotL64(aOrbiterH, 3U)) + aOrbiterC) + aPhaseBWandererUpdateSaltE[(((31U - aIndex) + 7U)) & S_SALT1]);
