            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterH = ((aWandererG + RotL64(aIngress, 34U)) + RotL64(aCarry, 27U)) + 0xC3110DDDDA5DC650ULL;
            aOrbiterE = (aWandererE + RotL64(aScatter, 57U)) + 0x092A105F5AF0347EULL;
            aOrbiterJ = (aWandererD + RotL64(aPrevious, 13U)) + 0x162EFE03C1CE832FULL;
            aOrbiterG = ((aWandererK + RotL64(aCross, 21U)) + 0x6E4F2CD56483C8C5ULL) + aPhaseBOrbiterAssignSaltF[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterK = ((aWandererH + RotL64(aPrevious, 43U)) + 0xB4FDAFE46F179272ULL) + aPhaseBOrbiterAssignSaltC[(((31U - aIndex) + 13U)) & S_SALT1];
