            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0x7649234F0241BA59ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterD) ^ 0xB7935AA50E10C64DULL) ^ aPhaseBOrbiterUpdateSaltE[(((31U - aIndex) + 5U)) & S_SALT1];
