            aCross ^= RotL64(aKeyRowReadA[(((2047U - aIndex) + 6147U)) & W_KEY1], 35U);
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aIngress, 40U) ^ RotL64(aCross, 53U)) ^ (RotL64(aPrevious, 5U) + RotL64(aCarry, 23U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterH = (aWandererA + RotL64(aScatter, 37U)) + 0x6CFE24478C563CD2ULL;
            aOrbiterF = (aWandererJ + RotL64(aCross, 11U)) + 0x541849E2884D579AULL;
            aOrbiterB = ((aWandererH + RotL64(aIngress, 47U)) + RotL64(aCarry, 51U)) + 0x972BDE8DAAC63538ULL;
            aOrbiterD = ((aWandererF + RotL64(aPrevious, 5U)) + 0x64876DDE5620CF7DULL) + aPhaseBOrbiterAssignSaltE[((aIndex + 19U)) & S_SALT1];
            aOrbiterK = (aWandererD + RotL64(aCross, 29U)) + 0x7A6463C1F9DA6B3BULL;
            aOrbiterG = ((aWandererG + RotL64(aPrevious, 21U)) + RotL64(aCarry, 3U)) + 0xF91A1C27527F4244ULL;
            aOrbiterJ = (((aWandererE + RotL64(aScatter, 60U)) + RotL64(aCarry, 39U)) + 0x9E629273B5EA491DULL) + aPhaseBOrbiterAssignSaltD[((aIndex + 7U)) & S_SALT1];
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0xC708AEC7BE0823D8ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0xE8DA358A2B789C62ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xE8A98BC492A3E1A3ULL), 53U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0xA9D843BA65921BC8ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterD) ^ 0x456D71CCF9232E17ULL) ^ aPhaseBOrbiterUpdateSaltF[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x71F382A65F48B7B5ULL), 27U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x1E0BC8AD3EDA2C58ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterG) ^ 0x4A1C1F273F14D823ULL;
