            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterB) + 0xBF68578167291BA6ULL) + aPhaseBOrbiterUpdateSaltA[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0x053E76938B2AAFECULL;
            aOrbiterK = RotL64((aOrbiterK * 0x9FA2A28B8EEB6551ULL), 35U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterJ) + 0x41346A964B8F05ECULL) + aPhaseBOrbiterUpdateSaltC[((aIndex + 15U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0xBE51BFA4C447A9C1ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xBB08A894D69C3A6FULL), 47U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0xC55753F52CDDC827ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterB) ^ 0x79E4F9EE6C1BDF91ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x7C7DD2F74CCF9113ULL), 11U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterG) + 0xD673196BA3D35A9BULL) + aPhaseBOrbiterUpdateSaltB[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0xB5B86951A7C8E362ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x5B412A3E7DEF9951ULL), 5U);
            //
            aIngress = RotL64(aOrbiterG, 41U) ^ aOrbiterF;
            aIngress = aIngress + (RotL64(aOrbiterK, 13U) ^ aOrbiterJ);
            aIngress = aIngress + (RotL64(aOrbiterH, 47U) ^ aOrbiterD);
