            aIngress ^= (RotL64(aSpiritLaneD[((aIndex + 4546U)) & S_BLOCK1], 52U) ^ RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 433U)) & S_BLOCK1], 41U));
            aIngress = TwistMix64::DiffuseC(aIngress);
