            aCross = (RotL64(aHeartLaneC[((S_BLOCK1 - aIndex + 6033U)) & S_BLOCK1], 3U) ^ RotL64(aHeartLaneD[((S_BLOCK1 - aIndex + 1899U)) & S_BLOCK1], 40U));
