            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aIngress, 41U) ^ RotL64(aCross, 5U)) + (RotL64(aPrevious, 53U) ^ RotL64(aCarry, 28U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterE = ((aWandererA + RotL64(aPrevious, 57U)) + 0xC8D395A37C3EFE69ULL) + aPhaseBOrbiterAssignSaltE[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterD = ((aWandererJ + RotL64(aCross, 30U)) + RotL64(aCarry, 5U)) + 0xDEC89E23ED0F1EA5ULL;
            aOrbiterC = ((aWandererD + RotL64(aIngress, 5U)) + RotL64(aCarry, 41U)) + 0x779F2FEC77581C2DULL;
            aOrbiterH = (aWandererK + RotL64(aScatter, 11U)) + 0x45B91B399533B744ULL;
            aOrbiterJ = ((aWandererG + RotL64(aIngress, 51U)) + 0x2A38EE58A89D0EC6ULL) + aPhaseBOrbiterAssignSaltA[((aIndex + 3U)) & S_SALT1];
            aOrbiterF = (aWandererC + RotL64(aScatter, 23U)) + 0x17466CE06064906DULL;
            aOrbiterI = ((aWandererB + RotL64(aPrevious, 41U)) + RotL64(aCarry, 21U)) + 0xE4D648E810C4C376ULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0x143F658A3587A3A4ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterE) ^ 0x2E5CE5460F1D0AA3ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x319A8E1E87F5A959ULL), 13U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x142D06DC9DCAC0A1ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterC) ^ 0x1B7C929890574614ULL) ^ aPhaseBOrbiterUpdateSaltF[((aIndex + 27U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x3FA711A049EEEF69ULL), 47U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterC) + 0x375774C97CEDD24FULL) + aPhaseBOrbiterUpdateSaltD[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterF) ^ 0x6B6D8FDAD7A5F0CDULL;
            aOrbiterI = RotL64((aOrbiterI * 0x29D643EE13211EE5ULL), 39U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0xDD6258945578225FULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0xFECA5AF0F4B2E110ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x17890156908C05D9ULL), 27U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0xE3038B0C87808D47ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0xC370D2FD4F059C68ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x3F39D0BA49DD19E1ULL), 53U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterJ) + 0x4501A2D149C4A605ULL) + aPhaseBOrbiterUpdateSaltE[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0x78A40859694A19E5ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x9C820B08B5F7B987ULL), 19U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0x8E2D3DEA23144B9FULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterD) ^ 0xB383539BBC80E251ULL) ^ aPhaseBOrbiterUpdateSaltC[((aIndex + 15U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x0C8732263A391831ULL), 3U);
            //
            aIngress = RotL64(aOrbiterF, 21U) ^ aOrbiterE;
