            //
            aWandererB = aWandererB ^ ((RotL64(aScatter, 57U) + RotL64(aOrbiterD, 6U)) + aOrbiterJ);
            aWandererC = aWandererC + (((RotL64(aCross, 5U) + aOrbiterJ) + RotL64(aOrbiterI, 13U)) + RotL64(aCarry, 23U));
            aWandererG = aWandererG ^ ((RotL64(aPrevious, 23U) + aOrbiterF) + RotL64(aOrbiterI, 21U));
